#!/usr/bin/env bash
# Social-DL All-in-One App
# Version: 2.4.6
# Auto-generated - Edit source files instead!
# Repository: https://github.com/socialawkward/social-dl

set -o errexit
set -o nounset
set -o pipefail

# Farben
GREEN='\033[0;32m'
BLUE='\033[0;34m'
NC='\033[0m'

# Temporäres Arbeitsverzeichnis
TEMP_DIR=$(mktemp -d /tmp/social-dl-app-XXXXXX)
trap 'rm -rf "$TEMP_DIR"' EXIT

echo -e "${BLUE}📦 Social-DL App v2.4.6${NC}"
echo "Extracting files..."


# === social-dl.sh ===
cat << 'EOF_social_dl_sh' | base64 -d > "$TEMP_DIR/social-dl.sh"

EOF_social_dl_sh
chmod +x "$TEMP_DIR/social-dl.sh"

# === install.sh ===
cat << 'EOF_install_sh' | base64 -d > "$TEMP_DIR/install.sh"

EOF_install_sh
chmod +x "$TEMP_DIR/install.sh"

# === install-gui.sh ===
cat << 'EOF_install_gui_sh' | base64 -d > "$TEMP_DIR/install-gui.sh"

EOF_install_gui_sh
chmod +x "$TEMP_DIR/install-gui.sh"

# === uninstall-gui.sh ===
cat << 'EOF_uninstall_gui_sh' | base64 -d > "$TEMP_DIR/uninstall-gui.sh"

EOF_uninstall_gui_sh
chmod +x "$TEMP_DIR/uninstall-gui.sh"

# === README.md ===
cat << 'EOF_README_md' | base64 -d > "$TEMP_DIR/README.md"

EOF_README_md

# === README.en.md ===
cat << 'EOF_README_en_md' | base64 -d > "$TEMP_DIR/README.en.md"

EOF_README_en_md

# === DEVELOPMENT-NOTES.md ===
cat << 'EOF_DEVELOPMENT_NOTES_md' | base64 -d > "$TEMP_DIR/DEVELOPMENT-NOTES.md"

EOF_DEVELOPMENT_NOTES_md

# === LICENSE ===
cat << 'EOF_LICENSE' | base64 -d > "$TEMP_DIR/LICENSE"

EOF_LICENSE

# === social-dl-installer.desktop ===
cat << 'EOF_social_dl_installer_desktop' | base64 -d > "$TEMP_DIR/social-dl-installer.desktop"

EOF_social_dl_installer_desktop

# === social-dl-uninstaller.desktop ===
cat << 'EOF_social_dl_uninstaller_desktop' | base64 -d > "$TEMP_DIR/social-dl-uninstaller.desktop"

EOF_social_dl_uninstaller_desktop

# === GUI MENU ===

if ! command -v zenity >/dev/null 2>&1; then
    echo "Error: zenity not installed"
    echo "Arch: sudo pacman -S zenity"
    echo "Debian/Ubuntu: sudo apt install zenity"
    exit 1
fi

cd "$TEMP_DIR"

# Standard-Sprache: Deutsch
LANG_MODE="de"

show_menu() {
    local lang="$1"
    
    if [ "$lang" = "de" ]; then
        # Deutsches Menü - Smartphone Design mit Icons
        CHOICE=$(zenity --list \
            --title="Social-DL v2.4.6" \
            --width=420 --height=520 \
            --window-icon="applications-multimedia" \
            --text="<big><b>📱 Social-DL</b></big>\n<small>Universal Social Media Downloader</small>" \
            --column="ID" --column="Option" --column="Beschreibung" \
            "1" "📥 Installieren" "Auf diesem System installieren" \
            "2" "🗑️  Deinstallieren" "Von diesem System entfernen" \
            "3" "📖 README (DE)" "Deutsche Dokumentation" \
            "4" "📘 README (EN)" "Englische Dokumentation" \
            "5" "🚀 Ausführen" "Social-DL jetzt starten" \
            "6" "ℹ️  Info" "Über Social-DL" \
            "7" "🌐 English" "Switch language" \
            "8" "❌ Beenden" "Programm schließen" \
            --hide-column=1 --print-column=1 2>/dev/null)
    else
        # Englisches Menü - Smartphone Design mit Icons
        CHOICE=$(zenity --list \
            --title="Social-DL v2.4.6" \
            --width=420 --height=520 \
            --window-icon="applications-multimedia" \
            --text="<big><b>📱 Social-DL</b></big>\n<small>Universal Social Media Downloader</small>" \
            --column="ID" --column="Option" --column="Description" \
            "1" "📥 Install" "Install on this system" \
            "2" "🗑️  Uninstall" "Remove from this system" \
            "3" "📖 README (DE)" "German documentation" \
            "4" "📘 README (EN)" "English documentation" \
            "5" "🚀 Run now" "Start Social-DL now" \
            "6" "ℹ️  Info" "About Social-DL" \
            "7" "🌐 Deutsch" "Sprache wechseln" \
            "8" "❌ Exit" "Close program" \
            --hide-column=1 --print-column=1 2>/dev/null)
    fi
    
    echo "$CHOICE"
}

while true; do
    CHOICE=$(show_menu "$LANG_MODE")
    
    # Exit wenn Cancel gedrückt
    [ $? -ne 0 ] && exit 0
    
    case "$CHOICE" in
        "1")  # Installieren
            if bash "./install-gui.sh"; then
                if [ "$LANG_MODE" = "de" ]; then
                    zenity --info --window-icon="applications-multimedia" --text="<span size='large'>✅</span>\n\n<b>Installation erfolgreich!</b>\n\nSocial-DL wurde installiert." --width=320 --title="Erfolg"
                else
                    zenity --info --window-icon="applications-multimedia" --text="<span size='large'>✅</span>\n\n<b>Installation successful!</b>\n\nSocial-DL has been installed." --width=320 --title="Success"
                fi
            else
                if [ "$LANG_MODE" = "de" ]; then
                    zenity --error --window-icon="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Installation fehlgeschlagen!</b>\n\nBitte Fehlermeldung prüfen." --width=320 --title="Fehler"
                else
                    zenity --error --window-icon="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Installation failed!</b>\n\nPlease check error messages." --width=320 --title="Error"
                fi
            fi
            ;;
        "2")  # Deinstallieren
            if bash "./uninstall-gui.sh"; then
                if [ "$LANG_MODE" = "de" ]; then
                    zenity --info --window-icon="applications-multimedia" --text="<span size='large'>✅</span>\n\n<b>Deinstallation erfolgreich!</b>\n\nSocial-DL wurde entfernt." --width=320 --title="Erfolg"
                else
                    zenity --info --window-icon="applications-multimedia" --text="<span size='large'>✅</span>\n\n<b>Uninstallation successful!</b>\n\nSocial-DL has been removed." --width=320 --title="Success"
                fi
            else
                if [ "$LANG_MODE" = "de" ]; then
                    zenity --error --window-icon="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Deinstallation fehlgeschlagen!</b>\n\nBitte Fehlermeldung prüfen." --width=320 --title="Fehler"
                else
                    zenity --error --window-icon="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Uninstallation failed!</b>\n\nPlease check error messages." --width=320 --title="Error"
                fi
            fi
            ;;
        "3")  # README DE
            zenity --text-info --filename="./README.md" \
                --width=900 --height=700 \
                --window-icon="text-x-generic" \
                --title="📖 README (Deutsch)" \
                --font="Monospace 10"
            ;;
        "4")  # README EN
            zenity --text-info --filename="./README.en.md" \
                --width=900 --height=700 \
                --window-icon="text-x-generic" \
                --title="📘 README (English)" \
                --font="Monospace 10"
            ;;
        "5")  # Ausführen
            # Finde Terminal
            TERMINAL=""
            for term in x-terminal-emulator konsole gnome-terminal xfce4-terminal xterm; do
                if command -v "$term" >/dev/null 2>&1; then
                    TERMINAL="$term"
                    break
                fi
            done
            
            if [ -n "$TERMINAL" ]; then
                case "$TERMINAL" in
                    konsole)
                        konsole --workdir "$TEMP_DIR" -e bash -c "./social-dl.sh; echo ''; read -p 'Enter zum Schließen... / Press Enter to close...'"
                        ;;
                    gnome-terminal|xfce4-terminal)
                        $TERMINAL --working-directory="$TEMP_DIR" -- bash -c "./social-dl.sh; echo ''; read -p 'Enter zum Schließen... / Press Enter to close...'"
                        ;;
                    *)
                        $TERMINAL -e bash -c "cd '$TEMP_DIR' && ./social-dl.sh; echo ''; read -p 'Enter zum Schließen... / Press Enter to close...'"
                        ;;
                esac
            else
                if [ "$LANG_MODE" = "de" ]; then
                    zenity --error --width=360 --window-icon="dialog-error" --title="Fehler" \
                        --text="<b>Kein Terminal gefunden!</b>\n\nBitte führe social-dl.sh manuell aus:\n\n<tt>$TEMP_DIR/social-dl.sh</tt>"
                else
                    zenity --error --width=360 --window-icon="dialog-error" --title="Error" \
                        --text="<b>No terminal found!</b>\n\nPlease run social-dl.sh manually:\n\n<tt>$TEMP_DIR/social-dl.sh</tt>"
                fi
            fi
            ;;
        "6")  # Info
            if [ "$LANG_MODE" = "de" ]; then
                zenity --info --width=400 --height=420 --window-icon="help-about" --title="ℹ️  Über Social-DL" \
                    --text="<span size='x-large'><b>Social-DL</b></span>
<span size='small'>Version 2.4.6</span>

<b>Universal Video &amp; Audio Downloader</b>
für Social Media Plattformen

<b>📱 Unterstützte Plattformen:</b>
• Instagram
• Twitter / X
• YouTube
• Reddit
• TikTok

<b>💻 Entwickelt mit ❤️ von:</b>
• Grok (Basis &amp; Features)
• Claude (Security &amp; Production)
• Perplexity (Edge-Cases &amp; Optimierungen)

<b>🔗 Repository:</b>
<span foreground='#0969DA'>github.com/socialawkward/social-dl</span>

<b>📄 Lizenz:</b> MIT License"
            else
                zenity --info --width=400 --height=420 --window-icon="help-about" --title="ℹ️  About Social-DL" \
                    --text="<span size='x-large'><b>Social-DL</b></span>
<span size='small'>Version 2.4.6</span>

<b>Universal Video &amp; Audio Downloader</b>
for Social Media Platforms

<b>📱 Supported Platforms:</b>
• Instagram
• Twitter / X
• YouTube
• Reddit
• TikTok

<b>💻 Developed with ❤️ by:</b>
• Grok (Base &amp; Features)
• Claude (Security &amp; Production)
• Perplexity (Edge-Cases &amp; Optimizations)

<b>🔗 Repository:</b>
<span foreground='#0969DA'>github.com/socialawkward/social-dl</span>

<b>📄 License:</b> MIT License"
            fi
            ;;
        "7")  # Sprachwechsel
            if [ "$LANG_MODE" = "de" ]; then
                LANG_MODE="en"
            else
                LANG_MODE="de"
            fi
            ;;
        "8"|*)  # Beenden
            exit 0
            ;;
    esac
done
